window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[120]={"id":"120","numero":120,"titre":"Complications de l'immobilité et du décubitus","objectifs":[{"id":"120-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’immobilisation","contenu":"<p>L'<span class=\"kw-def\">immobilisation</span> (ou syndrome d'immobilisation) se définit par l'une des deux situations suivantes :</p>\n      <ul>\n        <li>un <span class=\"kw-clinique\">alitement</span> de <strong><span class=\"kw-chiffre\">&gt; 3 jours</span></strong> ;</li>\n        <li>une <span class=\"kw-clinique\">incapacité à réaliser les transferts</span> lit-fauteuil ou à se mouvoir.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Épidémiologie</span></strong> — le décubitus prolongé concerne très majoritairement le sujet âgé :</p>\n      <ul>\n        <li><span class=\"kw-chiffre\">90 %</span> des patients alités ont plus de <span class=\"kw-chiffre\">60 ans</span> ;</li>\n        <li><span class=\"kw-chiffre\">5-10 %</span> des sujets de plus de <span class=\"kw-chiffre\">85 ans</span> sont incapables de se mouvoir seuls ;</li>\n        <li><span class=\"kw-chiffre\">40 %</span> des résidents d'EHPAD restent au lit ou au fauteuil toute la journée ;</li>\n        <li>la perte de mobilité à domicile progresse de <span class=\"kw-chiffre\">3-4 %/an</span> (accélération chez <span class=\"kw-clinique\">les</span> plus âgés).</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> conséquences de l'alitement ne sont <strong>pas spécifiques</strong> de la personne âgée, mais y sont <strong>plus précoces, plus fréquentes et plus graves</strong>.</div>\n      <p><strong>Causes du syndrome d'immobilisation</strong> — étiologies multiples et souvent intriquées :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td>Musculo-squelettique</td><td><span class=\"kw-etio\">Arthrose</span> ; complication d'<span class=\"kw-def\">ostéoporose</span> (<span class=\"kw-etio\">fracture du col fémoral</span>, fractures vertébrales) ; arthrite ; chutes à répétition</td></tr>\n          <tr><td>Neurologique</td><td><span class=\"kw-etio\">AVC</span> ; neuropathies ; <span class=\"kw-etio\">maladie de Parkinson</span> ; maladie d'Alzheimer ; maladie à corps de Lewy</td></tr>\n          <tr><td>Cardiovasculaire</td><td><span class=\"kw-def\">Insuffisance cardiaque</span> ; <span class=\"kw-def\">syndrome coronarien aigu</span> ; <span class=\"kw-clinique\">hypotension</span> orthostatique</td></tr>\n          <tr><td>Pulmonaire</td><td>Pneumopathie aiguë ; <span class=\"kw-ci\">insuffisance respiratoire</span></td></tr>\n          <tr><td>Psychiatrique</td><td><span class=\"kw-etio\">Dépression</span> ; anxiété ; délire de persécution ; peur de tomber</td></tr>\n          <tr><td>Environnementaux et sociaux</td><td><span class=\"kw-etio\">Contention physique</span> ; iatrogénie hospitalière (sonde urinaire, perfusions, ridelles) ; manque d'aide humaine ; maltraitance</td></tr>\n          <tr><td>Douleurs aiguës / chroniques</td><td>Plaie ; maladie cancéreuse ; pathologie viscérale aiguë ; douleur neurogène</td></tr>\n          <tr><td>Iatrogénie médicamenteuse</td><td><span class=\"kw-ttt\">Psychotropes</span> ; traitements favorisant le risque de chute</td></tr>\n          <tr><td>Autres</td><td><span class=\"kw-etio\">Sarcopénie</span> ; <span class=\"kw-clinique\">cachexie</span> ; dénutrition sévère ; déconditionnement post-alitement ; situations post-chirurgicales</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Personne âgée malade · 133 — Autonomie-dépendance du sujet âgé</em></p>","frequence":0},{"id":"120-2","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir dépister les principaux éléments du syndrome de désadaptation psychomotrice","contenu":"<p>Le <span class=\"kw-def\">syndrome de désadaptation psychomotrice</span> (ou désadaptation posturale) est une <strong><span class=\"kw-alerte\">urgence gériatrique</span></strong> : son <span class=\"kw-def\">dépistage</span> précoce conditionne la récupération fonctionnelle.</p>\n      <p><strong>Mécanisme</strong> — le décubitus prolongé entrave la perception des informations <span class=\"kw-clinique\">visuelles</span>, <span class=\"kw-clinique\">vestibulaires</span>, <span class=\"kw-clinique\">proprioceptives</span> et <span class=\"kw-clinique\">somesthésiques</span>. Ce <span class=\"kw-def\">déconditionnement sensoriel</span> altère la perception de la verticale et désadapte la posture.</p>\n      <p><strong>Éléments à dépister</strong> :</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td>Rétropulsion</td><td><span class=\"kw-clinique\">Station debout impossible sans aide</span> ; tendance rétropulsive avec flexion des genoux au lever ; forme évoluée : appui talonnier et orteils en griffe</td></tr>\n          <tr><td>Stasobasophobie</td><td><span class=\"kw-clinique\">Phobie de la marche et de la verticalisation</span> ; le patient s'agrippe à l'examinateur ou au mobilier ; réactions anxieuses majeures à tout lâcher</td></tr>\n          <tr><td>Troubles de la marche</td><td>Petits pas glissés en appui talonnier sans déroulement du pas ; élargissement du polygone de sustentation ; retard d'initiation / <span class=\"kw-clinique\">freezing</span></td></tr>\n          <tr><td>Troubles neurologiques</td><td><span class=\"kw-clinique\">Hypertonie oppositionnelle</span> ; altération des réactions d'adaptation posturale et des réactions parachutes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> L'examen clinique est par ailleurs <strong>normal</strong>, notamment sur <span class=\"kw-clinique\">les</span> plans <span class=\"kw-clinique\">neurologique</span> et <span class=\"kw-clinique\">rhumatologique</span> — c'est ce qui distingue le <span class=\"kw-clinique\">syndrome de désadaptation</span> d'un déficit organique.</div>\n      <div class=\"callout callout-info\"><strong>CAT.</strong> <span class=\"kw-ttt\">Rééducation fonctionnelle posturale précoce</span>, débutée si besoin sur <span class=\"kw-ttt\">table de verticalisation</span> dès que l'état médical l'autorise.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 131 — Troubles de la marche et de l'équilibre du sujet âgé · 130 — Personne âgée malade</em></p>","frequence":1},{"id":"120-3","rang":"A","rubrique":"Définition","titre":"Connaître les principales complications précoces du décubitus","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">complications précoces</span> surviennent en <strong><span class=\"kw-chiffre\">heures à jours</span></strong> et persistent pendant toute la phase d'hypomobilité. Elles se classent en atteintes loco-régionales et générales :</p>\n      <table >\n        <thead><tr><th>Loco-régionales</th><th>Générales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-alerte\">Escarre</span><br>\n              <span class=\"kw-alerte\">Maladie thrombo-embolique veineuse (MTEV)</span><br>\n              <span class=\"kw-clinique\">Compressions nerveuses</span>\n            </td>\n            <td>\n              <strong>Urinaires :</strong> <span class=\"kw-clinique\">dysurie</span> ; <span class=\"kw-clinique\">infection urinaire</span><br>\n              <strong>Digestives :</strong> <span class=\"kw-clinique\">constipation</span> ; <span class=\"kw-clinique\">reflux gastrique</span> ; <span class=\"kw-clinique\">fausses routes</span> ; <span class=\"kw-clinique\">encombrement bronchique</span><br>\n              <strong>Métaboliques :</strong> <span class=\"kw-clinique\">rhabdomyolyse</span> ; <span class=\"kw-clinique\">déshydratation</span><br>\n              <strong>Neuro-psychiques :</strong> <span class=\"kw-clinique\">confusion</span><br>\n              <strong>Désadaptation :</strong> <span class=\"kw-clinique\">cardiaque</span> ; <span class=\"kw-alerte\">posturale / psychomotrice</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Urgences à ne pas manquer.</strong> Parmi <span class=\"kw-clinique\">les</span> complications précoces, l'<span class=\"kw-alerte\">escarre</span>, la <span class=\"kw-alerte\">MTEV</span> et le <span class=\"kw-alerte\">syndrome de désadaptation psychomotrice</span> engagent le <span class=\"kw-def\">pronostic</span> fonctionnel ou vital — toutes sont <strong>prévisibles et évitables</strong> par une prise en charge entreprise dès le début du décubitus.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 4 — Infection nosocomiale</em></p>","frequence":2},{"id":"120-4","rang":"B","rubrique":"Définition","titre":"Connaître les autres complications précoces et les complications tardives du décubitus","contenu":"<p>Au-delà des complications précoces majeures, le décubitus prolongé induit des <span class=\"kw-def\">complications tardives</span>, témoins de son impact systémique durable :</p>\n      <table >\n        <thead><tr><th>Loco-régionales</th><th>Générales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-clinique\">Rétractions musculaires</span><br>\n              <span class=\"kw-clinique\">Attitudes vicieuses</span>\n            </td>\n            <td>\n              <span class=\"kw-alerte\">Ostéoporose</span><br>\n              <span class=\"kw-clinique\">Troubles psychiques</span> (<span class=\"kw-def\">dépression</span>)<br>\n              <span class=\"kw-alerte\">Dénutrition</span><br>\n              <span class=\"kw-clinique\">Infection pulmonaire et urinaire</span><br>\n              <span class=\"kw-clinique\">Globe vésical</span> ; <span class=\"kw-clinique\">fécalome</span><br>\n              <span class=\"kw-clinique\">Dysautonomie</span> avec <span class=\"kw-clinique\">hypotension</span> orthostatique\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Ostéoporose</span> d'immobilisation</strong> — l'hypomobilité réduit l'ostéoformation et majore la résorption (<span class=\"kw-def\">hyperrésorption ostéoclastique</span>), prédominant sur l'<span class=\"kw-bio\">os trabéculaire</span> (rachis lombaire). Conséquences : <span class=\"kw-bio\">hypercalcémie</span> modérée, <span class=\"kw-bio\">hypercalciurie</span> exposant à la <span class=\"kw-alerte\">lithiase urinaire</span>, augmentation du risque fracturaire. Phénomènes <strong>réversibles</strong> à la reprise de l'appui.</p>\n      <p><strong>Troubles psychiques</strong> — réactions d'<span class=\"kw-clinique\">angoisse</span> (insomnie, plaintes somatiques, agitation), réactions <span class=\"kw-clinique\">dépressives</span>, <span class=\"kw-clinique\">régression psychologique</span> induite par la dépendance.</p>\n      <p><strong>Infections nosocomiales</strong> — infections contractées au-delà de <span class=\"kw-chiffre\">48 h</span> après l'admission, <span class=\"kw-etio\">endogènes</span> (autocontamination) ou <span class=\"kw-etio\">exogènes</span> (contamination croisée manuportée, environnementale). Favorisées par la durée de séjour, le <span class=\"kw-def\">terrain</span> et <span class=\"kw-clinique\">les</span> dispositifs invasifs.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 128 — Ostéopathie fragilisante · 250 — Dénutrition · 252 — Troubles nutritionnels du sujet âgé</em></p>","frequence":3},{"id":"120-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des complications du décubitus","contenu":"<p>L'immobilisation entraîne une <span class=\"kw-def\">cascade de dysfonctionnements multisystémiques</span>. Le décubitus, sans conséquence pour une nuit de sommeil chez le sujet sain, devient pathogène chez le patient alité incapable de changer de position ou de contracter ses muscles.</p>\n      <table >\n        <thead><tr><th>Système</th><th>Conséquences physiopathologiques</th></tr></thead>\n        <tbody>\n          <tr><td>Musculo-squelettique</td><td>↓ <span class=\"kw-clinique\">force</span> et <span class=\"kw-clinique\">masse musculaire</span> ; contractures ; souffrance cartilagineuse ; ankylose ; <span class=\"kw-alerte\">ostéoporose</span></td></tr>\n          <tr><td>Cardiovasculaire</td><td>↑ <span class=\"kw-clinique\">fréquence cardiaque de repos</span> ; ↓ perfusion myocardique ; <span class=\"kw-clinique\">hypotension orthostatique</span> ; ↓ <span class=\"kw-bio\">VO2max</span> ; <span class=\"kw-alerte\">congestion veineuse et hypercoagulabilité</span> (risque <span class=\"kw-etio\">thrombotique</span>)</td></tr>\n          <tr><td>Cutané</td><td>Risque d'<span class=\"kw-alerte\">escarre</span> et de macération</td></tr>\n          <tr><td>Métabolique et endocrinien</td><td><span class=\"kw-bio\">Balance azotée négative</span> ; <span class=\"kw-bio\">hypercalcémie</span> ; natriurèse ; <span class=\"kw-bio\">insulinorésistance</span> ; ↓ absorption des vitamines et minéraux</td></tr>\n          <tr><td>Neurologique et psychiatrique</td><td><span class=\"kw-clinique\">Dépression</span> ; <span class=\"kw-clinique\">confusion</span> ; troubles cognitifs ; troubles de l'équilibre ; compression nerveuse</td></tr>\n          <tr><td>Gastro-intestinal et urinaire</td><td><span class=\"kw-clinique\">Incontinence</span> ; rétention urinaire ; <span class=\"kw-clinique\">constipation</span> ; <span class=\"kw-clinique\">RGO</span> ; <span class=\"kw-clinique\">pneumopathie d'inhalation</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Physiopathologie</span> de l'escarre.</strong> Lorsque la <span class=\"kw-def\">pression des parties molles</span> sur le plan d'appui dépasse la <strong><span class=\"kw-chiffre\">pression de perfusion capillaire (32 mmHg)</span></strong> : <span class=\"kw-clinique\">ischémie</span> → phénomène <span class=\"kw-etio\">inflammatoire</span> favorisant un <span class=\"kw-clinique\">thrombus</span> → <span class=\"kw-clinique\">anoxie</span> → <span class=\"kw-alerte\">nécrose tissulaire</span>. L'escarre est donc d'origine <strong><span class=\"kw-etio\">ischémique</span></strong> et peut survenir dès <span class=\"kw-chiffre\">3 à 4 h</span> d'appui, parfois <span class=\"kw-chiffre\">2 h</span> si la pression est importante.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 343 — Etat confusionnel - trouble de conscience</em></p>","frequence":0},{"id":"120-6","rang":"A","rubrique":"Prise en charge","titre":"Savoir prévenir les complications précoces du décubitus","contenu":"<p>La prévention est le cœur de cet item (objectif le plus tombé). Elle est <strong>débutée dès l'admission</strong>, adaptée au niveau de risque, et engage l'ensemble de l'équipe soignante.</p>\n\n      <p><strong>1 · Prévention des escarres</strong></p>\n      <p>Évaluation du risque cutané par une échelle validée — <span class=\"kw-def\">échelle de Braden</span> (la plus utilisée), Norton ou Waterlow :</p>\n      <table >\n        <thead><tr><th>Échelle de Braden</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Critères (6)</td><td>Perception sensorielle ; humidité ; activité ; mobilité ; nutrition ; frictions et cisaillements</td></tr>\n          <tr><td><span class=\"kw-def\">Score</span></td><td>Total sur <span class=\"kw-chiffre\">23 points</span> — plus le <span class=\"kw-def\">score</span> est bas, plus le risque est élevé</td></tr>\n          <tr><td>Interprétation</td><td><span class=\"kw-chiffre\">≥ 19</span> : risque faible ; <span class=\"kw-chiffre\">15-18</span> : modéré ; <span class=\"kw-chiffre\">≤ 15</span> : élevé ; <span class=\"kw-chiffre\">≤ 12</span> : très élevé</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Soins de nursing :</strong> hygiène cutanée sans friction, effleurages des zones à risque, <span class=\"kw-clinique\">changements de position toutes les 2-3 h</span> ;</li>\n        <li><strong>Supports :</strong> matelas / surmatelas statiques (faible risque, alitement court) ou <span class=\"kw-ttt\">dynamiques</span> (risque élevé, alitement &gt;<span class=\"kw-chiffre\"> 15-20 h</span>/j) ;</li>\n        <li><strong>Nutrition :</strong> équilibre nutritionnel et hydratation — la majoration des apports n'est justifiée <strong>que si escarre constituée</strong>, pas en prévention pure ;</li>\n        <li><strong>À éviter :</strong> <span class=\"kw-ci\">frottements</span>, <span class=\"kw-ci\">cisaillement</span>, <span class=\"kw-ci\">massages</span> et <span class=\"kw-ci\">pétrissages</span> des zones d'appui ; limiter le temps tête de lit relevée.</li>\n      </ul>\n\n      <p><strong>2 · Prévention thrombo-<span class=\"kw-etio\">embolique</span> (MTEV)</strong></p>\n      <p>Indiquée chez le patient de <span class=\"kw-chiffre\">&gt; 40 ans</span> hospitalisé <span class=\"kw-chiffre\">&gt; 3 jours</span> pour une affection médicale aiguë associée à des <span class=\"kw-def\">facteurs de risque</span>.</p>\n      <ul>\n        <li><strong>Moyens non <span class=\"kw-etio\">médicamenteux</span> :</strong> <span class=\"kw-ttt\">compression veineuse élastique</span> ; verticalisation et reprise de la marche aussi précoces que possible ; électromyostimulation ;</li>\n        <li><strong>Anticoagulation préventive :</strong> <span class=\"kw-ttt\">HBPM</span> ou <span class=\"kw-ttt\">fondaparinux</span> à privilégier (moins de risque <span class=\"kw-etio\">hémorragique</span> et de TIH) ; <span class=\"kw-ttt\">HNF</span> si <span class=\"kw-ci\">insuffisance rénale sévère</span> ; durée <span class=\"kw-chiffre\">7 à 14 jours</span> en milieu médical.</li>\n      </ul>\n\n      <p><strong>3 · Prévention du <span class=\"kw-clinique\">RGO</span> et des fausses routes</strong></p>\n      <ul>\n        <li>Position assise ou demi-assise pour la prise des repas et <span class=\"kw-chiffre\">1 h</span> après ;</li>\n        <li>Hygiène bucco-dentaire ; adaptation des textures (eau gélifiée, alimentation mixée) ; <span class=\"kw-ttt\">verre à encoche nasale</span> ;</li>\n        <li><span class=\"kw-ci\">Verre à bec verseur à proscrire</span> — il impose une extension cervicale délétère.</li>\n      </ul>\n\n      <p><strong>4 · Prévention des autres complications</strong></p>\n      <table >\n        <thead><tr><th>Complication</th><th>Mesures préventives</th></tr></thead>\n        <tbody>\n          <tr><td>Désadaptation cardiaque</td><td>Rééducation active pendant le décubitus ; réentraînement à l'effort progressif sous <span class=\"kw-def\">surveillance</span> du rythme et de la TA</td></tr>\n          <tr><td><span class=\"kw-clinique\">Œdèmes</span></td><td>Contention élastique ; surélévation des membres ; contractions musculaires actives</td></tr>\n          <tr><td>Compressions nerveuses</td><td>Installation correcte ; changements réguliers de position ; orthèses de positionnement</td></tr>\n          <tr><td>Complications musculaires et articulaires</td><td>Mobilisations articulaires ; étirements ; postures alternées ; travail musculaire actif</td></tr>\n          <tr><td><span class=\"kw-clinique\">Constipation</span></td><td>Apports hydriques suffisants ; fibres ; verticalisation précoce ; massages abdominaux</td></tr>\n          <tr><td>Complications urinaires</td><td><span class=\"kw-def\">Dépistage</span> du <span class=\"kw-bio\">résidu post-mictionnel</span> ; sondages intermittents ; diurèse <span class=\"kw-chiffre\">≥ 1,5 L/24 h</span> ; éviter la sonde à demeure</td></tr>\n          <tr><td>Complications broncho-pulmonaires</td><td><span class=\"kw-ttt\">Kinésithérapie de désencombrement</span> dès <span class=\"kw-clinique\">les</span> premiers signes ; hydratation ; repas en position assise</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Toutes ces complications sont <strong>prévisibles</strong> : la prévention débute dès l'admission, repose sur la <span class=\"kw-ttt\">mobilisation et la verticalisation précoces</span>, et constitue une démarche pluridisciplinaire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 250 — Dénutrition</em></p>","frequence":6},{"id":"120-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères principaux des différents stades d’escarre","contenu":"<p>L'escarre concerne environ <span class=\"kw-chiffre\">300 000</span> patients en France. Sa gravité se cote en <span class=\"kw-def\">stades</span>, du plus superficiel au plus profond :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Profondeur</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Stade</span> 0 — hyperhémie réactionnelle</td><td>Pas d'atteinte</td><td><span class=\"kw-clinique\">Érythème disparaissant à la pression</span> puis réapparaissant ; <strong>réversible</strong> en <span class=\"kw-chiffre\">&lt; 24 h</span> par la mise en décharge</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> 1 — pas d'effraction cutanée</td><td>Épiderme intact</td><td><span class=\"kw-clinique\">Érythème persistant ne disparaissant pas à la pression</span> ; sur peau p<span class=\"kw-chiffre\">igm</span>entée : modification de chaleur, de consistance (<span class=\"kw-clinique\">œdème</span>, induration) ou de sensibilité</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> 2</td><td>Épiderme et derme</td><td><span class=\"kw-clinique\">Ulcération</span> superficielle ; <span class=\"kw-clinique\">abrasion</span> ; <span class=\"kw-clinique\">phlyctène</span></td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> 3</td><td>Plans sous-cutanés jusqu'au fascia (sans le dépasser)</td><td><span class=\"kw-alerte\">Ulcération profonde</span> ; volume de <span class=\"kw-clinique\">nécrose</span> souvent sous-estimé</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> 4</td><td>Au-delà du fascia : muscle, tendon, os</td><td>Destruction tissulaire majeure ; <span class=\"kw-alerte\">risque d'ostéite et d'arthrite</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Localisations</strong> — <span class=\"kw-clinique\">les</span> escarres siègent en regard des proéminences osseuses, variables selon la position :</p>\n      <table >\n        <thead><tr><th>Position</th><th>Zones exposées</th></tr></thead>\n        <tbody>\n          <tr><td>Décubitus dorsal</td><td>Occiput ; épines des scapulas ; <span class=\"kw-clinique\">région sacrée</span> ; <span class=\"kw-clinique\">talons</span></td></tr>\n          <tr><td>Décubitus ventral</td><td>Épines iliaques antérieures ; dos du pied ; crête tibiale</td></tr>\n          <tr><td>Décubitus latéral</td><td>Oreille ; acromion ; coude ; <span class=\"kw-clinique\">grand trochanter</span> ; malléoles</td></tr>\n          <tr><td>Station assise</td><td><span class=\"kw-clinique\">Ischions</span> ; région sacro-coccygienne</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Complications de l'escarre constituée.</strong> Locales : <span class=\"kw-clinique\">fistule</span>, extension de la <span class=\"kw-clinique\">nécrose</span>, perforation, <span class=\"kw-alerte\">risque de cancérisation</span> (<span class=\"kw-def\">surveillance</span> au long cours, même après cicatrisation). Générales : <span class=\"kw-alerte\">septicémie</span>, <span class=\"kw-alerte\">choc septique</span>, embolies septiques, <span class=\"kw-def\">endocardite</span>, anémie, dénutrition.</div>","frequence":3},{"id":"120-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux facteurs de risque d’escarre","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">facteurs de risque</span> d'escarre se répartissent en facteurs <strong>extrinsèques</strong> (liés à l'appui) et <strong>intrinsèques</strong> (liés au patient).</p>\n\n      <p><strong>Facteurs extrinsèques</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Intensité et durée de la pression</span> sur <span class=\"kw-clinique\">les</span> zones d'appui ;</li>\n        <li><span class=\"kw-etio\">Frictions</span> agressant directement la peau ;</li>\n        <li><span class=\"kw-etio\">Cisaillement</span>, surtout en positions assise ou demi-assise (glissement du patient) ;</li>\n        <li><span class=\"kw-etio\">Macération</span> liée à la sudation ou à l'incontinence ;</li>\n        <li>Éléments traumatisants en zone d'appui : plis de drap, miettes, contention.</li>\n      </ul>\n\n      <p><strong>Facteurs intrinsèques</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Hypovolémie</span>, <span class=\"kw-etio\">anémie</span>, <span class=\"kw-etio\">hypoxie</span> — réduisent l'oxygénation cutanée ;</li>\n        <li>Lésions cutanées préexistantes (cicatrices, brûlures, atrophie des plans de couverture) ;</li>\n        <li><span class=\"kw-etio\">Obésité</span> (majore la pression d'appui) et <span class=\"kw-etio\">maigreur / dénutrition</span> (perte du rôle amortisseur des plans sous-cutanés) ;</li>\n        <li><span class=\"kw-etio\">Incontinences</span> urinaire et fécale (macération + agression chimique + milieu septique) ;</li>\n        <li>Maladies neurologiques : déficit sensitivo-moteur, mouvements incontrôlés, positions vicieuses ;</li>\n        <li><span class=\"kw-etio\">Troubles de la conscience et de la vigilance</span> ; immobilité durant le sommeil.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> L'<strong>âge n'est pas un <span class=\"kw-def\">facteur de risque</span> indépendant</strong> d'escarre (selon la gériatrie) — <span class=\"kw-clinique\">les</span> personnes âgées sont plus touchées parce qu'elles cumulent davantage de <span class=\"kw-def\">comorbidités</span>.</div>\n\n      <p><strong>Autres <span class=\"kw-def\">facteurs de risque</span></strong></p>\n      <ul>\n        <li>Traitements : <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">cytotoxiques</span>, <span class=\"kw-ttt\">vasoconstricteurs</span> ;</li>\n        <li><span class=\"kw-def\">Comorbidités</span> : <span class=\"kw-etio\">diabète</span>, pathologie cardiovasculaire, <span class=\"kw-etio\">tabac</span>, troubles circulatoires et de la coagulation.</li>\n      </ul>\n\n      <p><strong>Facteurs précipitants</strong> (Collège de Gériatrie) : <span class=\"kw-etio\">hyperthermie</span>, <span class=\"kw-etio\">hypotension</span>, troubles de la conscience, incontinence (par macération), <span class=\"kw-clinique\">diarrhée</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 250 — Dénutrition · 128 — Ostéopathie fragilisante</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> le <span class=\"kw-alerte\">syndrome de désadaptation psychomotrice</span> est une <span class=\"kw-alerte\">urgence gériatrique</span> ; la thrombose (<span class=\"kw-etio\">MTEV</span>) peut survenir très tôt<br><strong>Fenêtre :</strong> escarre d'origine <span class=\"kw-etio\">ischémique</span> dès <span class=\"kw-chiffre\">3-4 h</span> d'appui (parfois <span class=\"kw-chiffre\">2 h</span> si forte pression), quand la pression d'appui dépasse la pression de perfusion capillaire (<span class=\"kw-chiffre\">32 mmHg</span>)<br><strong>1er geste :</strong> <span class=\"kw-ttt\">mise en décharge</span> de la zone d'appui — le <span class=\"kw-def\">stade 0</span> est réversible en <span class=\"kw-chiffre\">&lt; 24 h</span></p>","redflags":"<ul><li><span class=\"kw-alerte\">Syndrome de désadaptation psychomotrice</span> : rétropulsion, stasobasophobie (phobie de la verticalisation) = <span class=\"kw-alerte\">urgence gériatrique</span></li><li><span class=\"kw-etio\">Escarre stade 3-4</span> (atteinte du fascia, muscle, tendon ou os) → risque d'<span class=\"kw-etio\">ostéite</span> et d'<span class=\"kw-etio\">arthrite</span></li><li>Complications générales de l'escarre : <span class=\"kw-etio\">septicémie</span>, <span class=\"kw-alerte\">choc septique</span>, <span class=\"kw-etio\">embolies septiques</span>, <span class=\"kw-etio\">endocardite</span></li><li>Signes locaux de gravité : <span class=\"kw-clinique\">surinfection</span>, extension de la <span class=\"kw-clinique\">nécrose</span>, <span class=\"kw-clinique\">fistule</span>, perforation d'un viscère ou d'un vaisseau</li><li><span class=\"kw-etio\">Maladie thrombo-embolique veineuse</span> (MTEV) : peut survenir très précocement lors de l'immobilisation</li><li><span class=\"kw-clinique\">Fausses routes</span> : <span class=\"kw-clinique\">toux</span> perprandiale, voix gargouillante (« mouillée ») = <span class=\"kw-clinique\">stase laryngée</span> → risque de <span class=\"kw-etio\">pneumopathie d'inhalation</span></li></ul>","principes":"<p>Prise en charge surtout préventive, pluridisciplinaire, débutée dès l'admission ; traitement curatif de l'escarre adapté au <span class=\"kw-def\">stade</span>.</p><p><strong>Prévention de l'escarre (dès l'admission)</strong></p><p>Prévention pluridisciplinaire, adaptée au niveau de risque cutané, impliquant tout le personnel soignant</p><ul><li>Évaluer le risque cutané dès l'admission : <span class=\"kw-def\">échelle de Braden</span> (/23, risque élevé si <span class=\"kw-chiffre\">≤ 15</span>), Norton, Waterlow</li><li>Nursing : <span class=\"kw-ttt\">changements de position toutes les 2-3 h</span> (<span class=\"kw-chiffre\">3 h</span> en décubitus dorsal,<span class=\"kw-chiffre\"> 2 h</span> en décubitus latéral), soulever sans tracter, effleurages, hygiène sans friction</li><li>Supports : <span class=\"kw-ttt\">matelas/surmatelas</span> statique si risque faible (alité <span class=\"kw-chiffre\">&lt; 15 h/j</span>), dynamique si risque élevé (alité <span class=\"kw-chiffre\">&gt; 20 h/j</span>) ; lit fluidisé réservé à la réa / grands brûlés</li><li>Nutrition : équilibre nutritionnel et hydratation ; majoration des apports justifiée seulement si escarre constituée, pas en prévention</li><li>À éviter : <span class=\"kw-ci\">frictions, cisaillement, massages, glace, air chaud</span> ; limiter le temps tête relevée (favorise escarres sacrées et du talon)</li></ul><p><strong>Traitement curatif de l'escarre (selon le <span class=\"kw-def\">stade</span>)</strong></p><p>Traitement à la fois local et général, pluridisciplinaire</p><ul><li><span class=\"kw-def\">Stade 0-1</span> : <span class=\"kw-ttt\">suppression de l'appui</span> jusqu'au retour d'un aspect cutané normal + correction des <span class=\"kw-def\">facteurs de risque</span></li><li><span class=\"kw-def\">Stade 2</span> (phlyctène) : <span class=\"kw-ttt\">évacuer le contenu en maintenant si possible l'épiderme décollé</span> puis <span class=\"kw-ttt\">pansement hydrocolloïde ou gras</span></li><li><span class=\"kw-def\">Stade 3-4</span> / <span class=\"kw-clinique\">lésion</span> ouverte : nettoyage au <span class=\"kw-ttt\">sérum physiologique</span>, <span class=\"kw-ttt\">détersion</span> des nécroses/<span class=\"kw-bio\">fibrine</span>, pansement de recouvrement ; <span class=\"kw-ttt\">VAC</span> réservé aux échecs ; <span class=\"kw-ttt\">chirurgie</span> possible (excision, drainage, greffe/lambeau)</li><li><span class=\"kw-ttt\">Antibiothérapie générale</span> (sur prélèvement profond) uniquement si <span class=\"kw-alerte\">surinfection ou extension</span> régionale/générale</li><li>À proscrire : <span class=\"kw-ci\">antiseptiques et antibiotiques locaux</span>, prélèvement bactériologique sans signe d'infection</li></ul><p><strong>Thromboprophylaxie (MTEV)</strong></p><p>En post-<span class=\"kw-ttt\">chirurgie</span> : <span class=\"kw-ttt\">anticoagulation</span> seulement si risque modéré ou élevé (chirurgie de hanche : prolongée jusqu'à<span class=\"kw-chiffre\"> 5 semaines</span>)</p><ul><li>Indication en milieu médical : patient <span class=\"kw-chiffre\">&gt; 40 ans</span>, hospitalisé <span class=\"kw-chiffre\">&gt; 3 jours</span> pour pathologie aiguë associée à un <span class=\"kw-def\">facteur de risque</span></li><li><span class=\"kw-ttt\">HBPM</span> ou <span class=\"kw-ttt\">fondaparinux</span> à privilégier (<span class=\"kw-ttt\">énoxaparine</span> SC <span class=\"kw-chiffre\">4000 UI</span>/j ; <span class=\"kw-ttt\">fondaparinux</span> SC <span class=\"kw-chiffre\">2,5 mg</span>/j) — durée <span class=\"kw-chiffre\">7 à 14 jours</span></li><li><span class=\"kw-ttt\">HNF</span> SC (<span class=\"kw-chiffre\">5000 UI</span>/<span class=\"kw-chiffre\">12 h</span>) si <span class=\"kw-ci\">insuffisance rénale sévère</span> ou risque <span class=\"kw-etio\">hémorragique</span></li><li>Mesures non médicamenteuses : <span class=\"kw-ttt\">compression veineuse élastique</span>, verticalisation et reprise de la marche précoces</li></ul><p><strong>Autres complications — mesures clés</strong></p><ul><li><span class=\"kw-etio\">Désadaptation cardiaque/posturale</span> : <span class=\"kw-ttt\">rééducation</span> et réentraînement à l'effort progressifs, <span class=\"kw-ttt\">table de verticalisation</span> dès que possible</li><li><span class=\"kw-etio\">RGO</span> / <span class=\"kw-etio\">fausses routes</span> : position assise ou demi-assise <span class=\"kw-chiffre\">1 h</span> après <span class=\"kw-clinique\">les</span> repas, <span class=\"kw-ttt\">verre à encoche nasale</span>, tête en légère flexion, texture adaptée</li><li><span class=\"kw-etio\">Constipation</span> : hydratation, fibres, verticalisation, massages abdominaux, <span class=\"kw-ttt\">laxatifs osmotiques/lubrifiants</span></li><li><span class=\"kw-etio\">Complications urinaires</span> : <span class=\"kw-def\">dépistage</span> du <span class=\"kw-bio\">résidu post-mictionnel</span>, diurèse <span class=\"kw-chiffre\">≥ 1,5 L/24 h</span>, sondages intermittents (éviter la sonde à demeure)</li><li><span class=\"kw-etio\">Complications broncho-pulmonaires</span> : <span class=\"kw-ttt\">kinésithérapie de désencombrement</span> dès <span class=\"kw-clinique\">les</span> premiers signes, repas en position assise</li><li>Transversal : <span class=\"kw-ttt\">mobilisation précoce</span> (même passive), rééducation fonctionnelle, nutrition adaptée, stimulation cognitive et sociale</li></ul>","suivi":"<p><strong>Cutané :</strong> inspection des zones d'appui plusieurs fois/jour (rougeur, macération) ; recherche systématique du <span class=\"kw-def\">stade 0</span><br><strong>Escarre cicatrisée :</strong> <span class=\"kw-def\">surveillance</span> au long cours — risque de <span class=\"kw-etio\">cancérisation</span> de l'escarre ou de la cicatrice<br><strong>Réentraînement à l'effort :</strong> surveillance du <span class=\"kw-clinique\">rythme cardiaque</span> et de la <span class=\"kw-clinique\">TA</span><br><strong>Urinaire :</strong> <span class=\"kw-def\">dépistage</span> du <span class=\"kw-bio\">RPM</span> même en cas de miction spontanée (<span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">uroscanner</span> au moindre doute)</p>"},"liensGlobaux":[{"href":"https://www.coloplastprofessional.fr/bibliotheque/Connaissance/informations/type-de-plaies/prevention-et-prise-en-charge-des-escarres/comprendre-lescarre-en-8-points-cles/?legalconsented=true","label":"Coloplast — Escarre en 8 points clés"},{"href":"https://institut.amelis-services.com/sante/autres/lescarre-definition-differents-stades-traitements/","label":"Amelis — Escarre (définition, stades, traitements)"},{"href":"https://pro.coloplast.fr/Global/France_HCP/Documents/WC_Coloplast_Echelle_de_Braden_0621.pdf","label":"Coloplast — Échelle de Braden (PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Rougeur ou lésion d'appui chez un patient alité — Évaluation cutanée des zones de pression","detail":"<h4>CAT — Escarre : <span class=\"kw-def\">stadification</span> et prise en charge — Classer le stade de l'escarre (0 à 4) pour adapter le traitement local</h4>","branches":[{"to":"q-effraction","label":"Évaluation de la lésion d'appui","color":"blue"}]},{"id":"q-effraction","kind":"decision","label":"Effraction cutanée (peau ouverte) ? — Présence d'une ulcération / plaie","branches":[{"to":"q-erytheme","label":"Non — peau intacte","color":"green"},{"to":"q-profondeur","label":"Oui — plaie ouverte","color":"red"}]},{"id":"q-erytheme","kind":"decision","label":"L'érythème disparaît-il à la pression ?","branches":[{"to":"t-stade0","label":"Oui — blanchit à la pression","color":"green"},{"to":"t-stade1","label":"Non — érythème persistant","color":"amber"}]},{"id":"t-stade0","kind":"terminal","label":"Stade 0 — hyperhémie réactionnelle","color":"green","detail":"<h4>Repère</h4><ul><li><span class=\"kw-clinique\">Érythème</span> qui disparaît à la pression puis réapparaît en quelques secondes</li><li>Signe d'alerte à rechercher systématiquement plusieurs fois par jour</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Mise en décharge</span> immédiate de la zone d'appui</li><li>Réversible en <span class=\"kw-chiffre\">&lt; 24 h</span></li></ul>"},{"id":"t-stade1","kind":"terminal","label":"Stade 1 — érythème persistant, sans effraction","color":"amber","detail":"<h4>Repère</h4><ul><li><span class=\"kw-clinique\">Érythème</span> qui ne disparaît pas à la pression (rouge ou violacé sur peau p<span class=\"kw-chiffre\">igm</span>entée)</li><li>Modifications associées : chaleur/froid, induration, douleur ou <span class=\"kw-clinique\">prurit</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Suppression de l'appui</span> jusqu'au retour d'un aspect cutané normal</li><li>Intensifier la correction des autres <span class=\"kw-def\">facteurs de risque</span></li></ul>"},{"id":"q-profondeur","kind":"decision","label":"Quelle est la profondeur de l'atteinte ?","branches":[{"to":"t-stade2","label":"Épiderme / derme (phlyctène, abrasion)","color":"amber"},{"to":"t-stade3","label":"Sous-cutané jusqu'au fascia","color":"red"},{"to":"t-stade4","label":"Dépasse le fascia (muscle, os)","color":"red"}]},{"id":"t-stade2","kind":"terminal","label":"Stade 2 — atteinte épiderme / derme","color":"amber","detail":"<h4><span class=\"kw-clinique\">Lésion</span></h4><ul><li><span class=\"kw-clinique\">Ulcération</span> superficielle, abrasion ou phlyctène</li></ul><h4>Conduite</h4><ul><li>Phlyctène : <span class=\"kw-ttt\">évacuer le contenu en maintenant si possible l'épiderme décollé</span></li><li>Puis <span class=\"kw-ttt\">pansement hydrocolloïde ou gras</span></li></ul>"},{"id":"t-stade3","kind":"terminal","label":"Stade 3 — atteinte sous-cutanée (fascia non dépassé)","color":"red","detail":"<h4><span class=\"kw-clinique\">Lésion</span></h4><ul><li><span class=\"kw-clinique\">Ulcération</span> profonde des plans cutanés et tissus sous-cutanés ; le fascia peut être atteint sans être dépassé</li><li>Volume de <span class=\"kw-clinique\">nécrose</span> souvent sous-estimé</li></ul><h4>Conduite</h4><ul><li>Nettoyage au <span class=\"kw-ttt\">sérum physiologique</span>, <span class=\"kw-ttt\">détersion</span> des nécroses / <span class=\"kw-bio\">fibrine</span></li><li>Pansement de recouvrement (pas de pansement idéal : choix selon l'état local)</li><li><span class=\"kw-ttt\">Antibiothérapie générale</span> seulement si <span class=\"kw-alerte\">surinfection ou extension</span> régionale/générale</li></ul><h4>À proscrire</h4><ul><li><span class=\"kw-ci\">Antiseptiques / antibiotiques locaux</span>, massages, frictions, glace</li><li>Prélèvement bactériologique en l'absence de signe d'infection</li></ul>"},{"id":"t-stade4","kind":"terminal","label":"Stade 4 — dépasse le fascia (muscle, tendon, os)","color":"red","detail":"<h4><span class=\"kw-clinique\">Lésion</span></h4><ul><li>Destruction importante des tissus sous-cutanés dépassant le fascia</li><li>Risque d'<span class=\"kw-etio\">ostéite</span> et d'<span class=\"kw-etio\">arthrite</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Détersion</span> + pansement de recouvrement</li><li><span class=\"kw-ttt\">Geste chirurgical</span> possible : excision d'<span class=\"kw-clinique\">abcès</span>, <span class=\"kw-ttt\">drainage</span> d'arthrite septique, greffe / lambeau</li><li><span class=\"kw-ttt\">Antibiothérapie générale</span> adaptée au prélèvement profond si surinfection / extension</li></ul>"}]},"cards":[{"i":"3eab7d5228f5","n":120,"o":"120-1","u":"Définition","t":"Connaître la définition d’immobilisation","q":"Quels types de iatrogénie médicamenteuse et d'autres facteurs peuvent conduire à un syndrome d'immobilisation ?","a":"<ul><li>Iatrogénie médicamenteuse : <strong>psychotropes</strong>, traitements favorisant le <strong>risque de chute</strong>.</li><li>Autres facteurs : <strong>sarcopénie</strong>, <strong>cachexie</strong>, <strong>dénutrition sévère</strong>, <strong>déconditionnement post-alitement</strong>, <strong>situations post-chirurgicales</strong>.</li></ul>"},{"i":"49796518d6a6","n":120,"o":"120-1","u":"Définition","t":"Connaître la définition d’immobilisation","q":"Quelle est la définition de l'immobilisation ou syndrome d'immobilisation, selon le consensus médical ?","a":"<p>L'immobilisation est définie par l'une des deux situations suivantes :</p><ul><li>Un <strong>alitement de plus de 3 jours</strong>.</li><li>Une <strong>incapacité à réaliser les transferts lit-fauteuil</strong> ou à <strong>se mouvoir seul</strong>.</li></ul>"},{"i":"6fafd742b0ed","n":120,"o":"120-1","u":"Définition","t":"Connaître la définition d’immobilisation","q":"Citez des facteurs environnementaux, sociaux et des causes de douleur pouvant provoquer un syndrome d'immobilisation.","a":"<ul><li>Facteurs environnementaux et sociaux : <strong>contention physique</strong>, <strong>iatrogénie hospitalière</strong> (sonde urinaire, perfusions, ridelles), <strong>manque d'aide humaine</strong>, <strong>maltraitance</strong>.</li><li>Douleurs : <strong>plaie</strong>, <strong>maladie cancéreuse</strong>, <strong>pathologie viscérale aiguë</strong>, <strong>douleur neurogène</strong>.</li></ul>"},{"i":"b00a8c266229","n":120,"o":"120-1","u":"Définition","t":"Connaître la définition d’immobilisation","q":"Quelles sont les principales causes musculo-squelettiques et neurologiques pouvant entraîner un syndrome d'immobilisation ?","a":"<ul><li>Causes musculo-squelettiques : <strong>arthrose</strong>, complications d'<strong>ostéoporose</strong> (fracture du col fémoral, fractures vertébrales), <strong>arthrite</strong>, <strong>chutes à répétition</strong>.</li><li>Causes neurologiques : <strong>AVC</strong>, <strong>neuropathies</strong>, <strong>maladie de Parkinson</strong>, <strong>maladie d'Alzheimer</strong>, <strong>maladie à corps de Lewy</strong>.</li></ul>"},{"i":"b20f190e9fa5","n":120,"o":"120-1","u":"Définition","t":"Connaître la définition d’immobilisation","q":"Quels sont les chiffres clés de l'épidémiologie du décubitus prolongé, notamment chez le sujet âgé ?","a":"<ul><li><strong>90 %</strong> des patients alités ont <strong>plus de 60 ans</strong>.</li><li><strong>5-10 %</strong> des sujets de <strong>plus de 85 ans</strong> sont incapables de se mouvoir seuls.</li><li><strong>40 %</strong> des résidents d'EHPAD sont alités ou restent au fauteuil toute la journée.</li><li>La perte de mobilité à domicile progresse de <strong>3-4 % par an</strong>.</li></ul>"},{"i":"b6c99feebf4b","n":120,"o":"120-1","u":"Définition","t":"Connaître la définition d’immobilisation","q":"Pourquoi les conséquences de l'alitement sont-elles particulièrement préoccupantes chez la personne âgée ?","a":"<p>Les conséquences de l'alitement ne sont pas spécifiques de la personne âgée, mais elles y sont <strong>plus précoces, plus fréquentes et plus graves</strong>.</p>"},{"i":"cae9c65c5c81","n":120,"o":"120-1","u":"Définition","t":"Connaître la définition d’immobilisation","q":"Quelles étiologies cardiovasculaires, pulmonaires et psychiatriques peuvent contribuer au syndrome d'immobilisation ?","a":"<ul><li>Causes cardiovasculaires : <strong>insuffisance cardiaque</strong>, <strong>syndrome coronarien aigu</strong>, <strong>hypotension orthostatique</strong>.</li><li>Causes pulmonaires : <strong>pneumopathie aiguë</strong>, <strong>insuffisance respiratoire</strong>.</li><li>Causes psychiatriques : <strong>dépression</strong>, <strong>anxiété</strong>, <strong>délire de persécution</strong>, <strong>peur de tomber</strong>.</li></ul>"},{"i":"0c0cfa1cf46a","n":120,"o":"120-2","u":"Identifier une urgence","t":"Savoir dépister les principaux éléments du syndrome de désadaptation psychomotrice","q":"Comment se manifestent la stasobasophobie et les troubles de la marche dans le syndrome de désadaptation psychomotrice ?","a":"<ul><li><strong>Stasobasophobie</strong> : phobie de la marche et de la verticalisation, le patient s'agrippe à l'examinateur ou au mobilier, réactions anxieuses majeures à tout lâcher.</li><li><strong>Troubles de la marche</strong> : petits pas glissés en appui talonnier sans déroulement du pas, élargissement du polygone de sustentation, <strong>retard d'initiation</strong> ou <strong>freezing</strong>.</li></ul>"},{"i":"16bd2cf167fb","n":120,"o":"120-2","u":"Identifier une urgence","t":"Savoir dépister les principaux éléments du syndrome de désadaptation psychomotrice","q":"Quelle est la prise en charge initiale recommandée pour le syndrome de désadaptation psychomotrice ?","a":"<p>La prise en charge consiste en une <strong>rééducation fonctionnelle posturale précoce</strong>, débutée si besoin sur <strong>table de verticalisation</strong> dès que l'état médical du patient l'autorise.</p>"},{"i":"4f466171eacd","n":120,"o":"120-2","u":"Identifier une urgence","t":"Savoir dépister les principaux éléments du syndrome de désadaptation psychomotrice","q":"Quelle est la définition du syndrome de désadaptation psychomotrice, et s'agit-il d'une urgence gériatrique ?","a":"<p>Le syndrome de désadaptation psychomotrice (ou désadaptation posturale) est un ensemble de troubles résultant d'un <strong>déconditionnement sensoriel</strong> (visuel, vestibulaire, proprioceptif, somesthésique) dû à un décubitus prolongé, qui altère la perception de la verticale et désadapte la posture. Il s'agit en effet d'une <strong>urgence gériatrique</strong>, où le dépistage précoce est crucial pour la récupération fonctionnelle.</p>"},{"i":"94b5cff62eb8","n":120,"o":"120-2","u":"Identifier une urgence","t":"Savoir dépister les principaux éléments du syndrome de désadaptation psychomotrice","q":"Quels sont les principaux éléments sémiologiques à dépister pour la rétropulsion dans le syndrome de désadaptation psychomotrice ?","a":"<ul><li><strong>Station debout impossible</strong> sans aide.</li><li>Tendance rétropulsive avec <strong>flexion des genoux au lever</strong>.</li><li>Forme évoluée : <strong>appui talonnier</strong> et <strong>orteils en griffe</strong>.</li></ul>"},{"i":"a1a2f06c8f76","n":120,"o":"120-2","u":"Identifier une urgence","t":"Savoir dépister les principaux éléments du syndrome de désadaptation psychomotrice","q":"Quelles sont les caractéristiques des troubles neurologiques et l'élément discriminant clé dans le syndrome de désadaptation psychomotrice ?","a":"<ul><li><strong>Troubles neurologiques</strong> : <strong>hypertonie oppositionnelle</strong>, altération des réactions d'adaptation posturale et des réactions parachutes.</li><li><strong>Discriminant clé</strong> : l'examen clinique est par ailleurs <strong>normal</strong> (notamment neurologique et rhumatologique), ce qui le distingue d'un déficit organique.</li></ul>"},{"i":"2ebdf4443e52","n":120,"o":"120-3","u":"Définition","t":"Connaître les principales complications précoces du décubitus","q":"Quelles sont les complications générales précoces du décubitus ?","a":"<ul><li>La <strong>maladie thrombo-embolique veineuse (MTEV)</strong>.</li><li>Les complications <strong>urinaires</strong> (dysurie, infection urinaire).</li><li>Les complications <strong>digestives</strong> (constipation, reflux gastrique, fausses routes, encombrement bronchique).</li><li>Les complications <strong>métaboliques</strong> (rhabdomyolyse, déshydratation).</li><li>Les complications <strong>neuro-psychiques</strong> (confusion).</li><li>La <strong>désadaptation</strong> (cardiaque, posturale/psychomotrice).</li></ul>"},{"i":"61e6f41ddd91","n":120,"o":"120-3","u":"Définition","t":"Connaître les principales complications précoces du décubitus","q":"Quelles sont les complications loco-régionales précoces du décubitus ?","a":"<ul><li>Les <strong>escarres</strong>.</li><li>Les <strong>compressions nerveuses</strong>.</li></ul>"},{"i":"b227d4302718","n":120,"o":"120-3","u":"Définition","t":"Connaître les principales complications précoces du décubitus","q":"Parmi les complications précoces du décubitus, lesquelles engagent le pronostic vital ou fonctionnel ?","a":"<p>Celles qui engagent le pronostic vital ou fonctionnel sont :</p><ul><li>L'<strong>escarre</strong>.</li><li>La <strong>maladie thrombo-embolique veineuse (MTEV)</strong>.</li><li>Le <strong>syndrome de désadaptation psychomotrice</strong>.</li></ul>"},{"i":"c4e550f6f81b","n":120,"o":"120-3","u":"Définition","t":"Connaître les principales complications précoces du décubitus","q":"Quelle est la définition des complications précoces du décubitus ?","a":"<p>Les complications précoces du décubitus sont celles qui surviennent rapidement, de quelques <strong>heures</strong> à quelques <strong>jours</strong> après le début de l'immobilité, et qui perdurent tant que persiste l'hypomobilité.</p>"},{"i":"64130dea46a7","n":120,"o":"120-6","u":"Prise en charge","t":"Savoir prévenir les complications précoces du décubitus","q":"Quels sont les principaux moyens de prévention des escarres chez un patient alité ?","a":"<ul><li><strong>Soins de nursing</strong>: hygiène cutanée sans friction, effleurages des zones à risque, changements de position toutes les <strong>2-3 heures</strong>.</li><li>Utilisation de <strong>supports</strong> adaptés: matelas/surmatelas statiques (faible risque, alitement court) ou dynamiques (risque élevé, alitement &gt; 15-20 h/jour).</li><li><strong>Nutrition</strong>: équilibre nutritionnel et hydratation.</li><li>À éviter: frottements, cisaillement, massages et pétrissages des zones d'appui, temps prolongé tête de lit relevée.</li></ul>"},{"i":"64a735980f80","n":120,"o":"120-6","u":"Prise en charge","t":"Savoir prévenir les complications précoces du décubitus","q":"Comment évalue-t-on le risque d'escarres chez un patient alité ?","a":"<p>Le risque d'escarres est évalué par une <strong>échelle validée</strong>, la plus utilisée étant l'<strong>échelle de Braden</strong>. D'autres échelles existent comme celles de Norton ou Waterlow.</p>"},{"i":"8b2712e7ebf5","n":120,"o":"120-6","u":"Prise en charge","t":"Savoir prévenir les complications précoces du décubitus","q":"Comment peut-on prévenir le reflux gastro-œsophagien (RGO) et les fausses routes chez le patient alité ?","a":"<ul><li>Maintenir une position <strong>assise ou demi-assise</strong> pour la prise des repas et <strong>1 heure après</strong>.</li><li>Assurer une bonne <strong>hygiène bucco-dentaire</strong>.</li><li>Adapter les <strong>textures</strong> des aliments (eau gélifiée, alimentation mixée).</li><li>Utiliser un <strong>verre à encoche nasale</strong> et proscrire le verre à bec verseur.</li></ul>"},{"i":"93fda5fd6b00","n":120,"o":"120-6","u":"Prise en charge","t":"Savoir prévenir les complications précoces du décubitus","q":"Quelles sont les actions clés pour prévenir les complications urinaires chez un patient immobilisé ?","a":"<ul><li><strong>Dépistage du résidu post-mictionnel</strong>.</li><li>Effectuer des <strong>sondages intermittents</strong> si nécessaire.</li><li>Maintenir une <strong>diurèse supérieure ou égale à 1,5 L/24h</strong>.</li><li><strong>Éviter la sonde à demeure</strong>.</li></ul>"},{"i":"bef7b85dd522","n":120,"o":"120-6","u":"Prise en charge","t":"Savoir prévenir les complications précoces du décubitus","q":"Quelles sont les mesures préventives pour les complications musculaires et articulaires liées à l'immobilité ?","a":"<ul><li><strong>Mobilisations articulaires</strong> régulières.</li><li><strong>Étirements</strong>.</li><li>Adopter des <strong>postures alternées</strong>.</li><li>Encourager le <strong>travail musculaire actif</strong>.</li></ul>"},{"i":"e2a64679fa3c","n":120,"o":"120-6","u":"Prise en charge","t":"Savoir prévenir les complications précoces du décubitus","q":"Quand est indiquée la prévention thrombo-embolique médicamenteuse chez un patient alité, et quels moyens sont utilisés ?","a":"<p>La prévention thrombo-embolique médicamenteuse est indiquée chez le patient de <strong>plus de 40 ans hospitalisé plus de 3 jours</strong> pour une affection médicale aiguë associée à des facteurs de risque.</p><ul><li><strong>Moyens non médicamenteux</strong>: compression veineuse élastique, verticalisation et reprise de la marche précoces, électromyostimulation.</li><li><strong>Anticoagulation préventive</strong>: <strong>HBPM</strong> ou <strong>fondaparinux</strong> (à privilégier), HNF si insuffisance rénale sévère.</li></ul>"},{"i":"183c7664beb4","n":120,"o":"120-7","u":"Diagnostic positif","t":"Connaître les critères principaux des différents stades d’escarre","q":"Quels sont les critères permettant de diagnostiquer un stade 1 d'escarre dans les complications de l'immobilité ?","a":"<p>Le stade 1 d'escarre est caractérisé par un <strong>érythème persistant ne disparaissant pas à la pression</strong>. L'<strong>épiderme est intact</strong>. Sur une peau pigmentée, on peut observer une modification de la chaleur, de la consistance (<strong>œdème, induration</strong>) ou de la sensibilité.</p>"},{"i":"3f422845bef0","n":120,"o":"120-7","u":"Diagnostic positif","t":"Connaître les critères principaux des différents stades d’escarre","q":"Quelle est la profondeur d'une escarre de stade 2 liée à l'immobilité ?","a":"<p>Une escarre de stade 2 en cas d'immobilité et de décubitus atteint l'<strong>épiderme et le derme</strong>. Elle se manifeste par une <strong>ulcération superficielle</strong>, une <strong>abrasion</strong> ou une <strong>phlyctène</strong>.</p>"},{"i":"54194edfb24a","n":120,"o":"120-7","u":"Diagnostic positif","t":"Connaître les critères principaux des différents stades d’escarre","q":"Décrivez les caractéristiques d'une escarre de stade 4 en lien avec l'immobilité et le décubitus.","a":"<p>Une escarre de stade 4 correspond à une <strong>destruction tissulaire majeure</strong>, s'étendant <strong>au-delà du fascia</strong> pour atteindre le <strong>muscle, le tendon ou l'os</strong>. Elle expose à un risque important d'<strong>ostéite</strong> et d'<strong>arthrite</strong>.</p>"},{"i":"7823a24ad46f","n":120,"o":"120-7","u":"Diagnostic positif","t":"Connaître les critères principaux des différents stades d’escarre","q":"Comment caractérise-t-on une escarre de stade 3 dans le cadre des complications de l'immobilité ?","a":"<p>Une escarre de stade 3 atteint les <strong>plans sous-cutanés jusqu'au fascia</strong>, sans le dépasser. Elle se présente comme une <strong>ulcération profonde</strong>, avec un volume de nécrose souvent sous-estimé.</p>"},{"i":"a7b10e223396","n":120,"o":"120-7","u":"Diagnostic positif","t":"Connaître les critères principaux des différents stades d’escarre","q":"Comment définit-on un stade 0 d'escarre concernant l'immobilité et le décubitus ?","a":"<p>Le stade 0 d'escarre correspond à une <strong>hyperhémie réactionnelle</strong>. Il n'y a pas d'atteinte cutanée. Cela se manifeste par un <strong>érythème disparaissant à la pression</strong>, puis réapparaissant. Cette lésion est <strong>réversible en moins de 24 heures</strong> par la mise en décharge.</p>"},{"i":"27a0696da091","n":120,"o":"120-8","u":"Diagnostic positif","t":"Connaître les principaux facteurs de risque d’escarre","q":"Quels sont les facteurs intrinsèques de risque d'escarre liés à l'état général du patient ?","a":"<p>Les facteurs intrinsèques de risque d'escarre liés à l'état général du patient incluent :</p><ul><li>L'<strong>hypovolémie</strong>, l'<strong>anémie</strong> et l'<strong>hypoxie</strong>, qui réduisent l'oxygénation cutanée.</li><li>Les <strong>lésions cutanées préexistantes</strong> (cicatrices, brûlures, atrophie des plans de couverture).</li><li>L'<strong>obésité</strong> (qui majore la pression d'appui) et la <strong>maigreur/dénutrition</strong> (qui entraîne une perte du rôle amortisseur des plans sous-cutanés).</li><li>Les <strong>incontinences urinaire et fécale</strong>, qui causent macération, agression chimique et un environnement septique.</li><li>Les <strong>maladies neurologiques</strong> avec déficit sensitivo-moteur, mouvements incontrôlés ou positions vicieuses.</li><li>Les <strong>troubles de la conscience et de la vigilance</strong>, ainsi que l'immobilité durant le sommeil.</li></ul>"},{"i":"4f9bd6fb99cf","n":120,"o":"120-8","u":"Diagnostic positif","t":"Connaître les principaux facteurs de risque d’escarre","q":"Quels sont les autres facteurs de risque d'escarre et le piège classique concernant l'âge ?","a":"<p>Les autres facteurs de risque d'escarre comprennent :</p><ul><li>Certains <strong>traitements</strong> : <strong>corticoïdes</strong>, <strong>cytotoxiques</strong>, <strong>vasoconstricteurs</strong>.</li><li>Des <strong>comorbidités</strong> telles que le <strong>diabète</strong>, les <strong>pathologies cardiovasculaires</strong>, le <strong>tabac</strong>, ainsi que les <strong>troubles circulatoires et de la coagulation</strong>.</li><li>Des facteurs <strong>précipitants</strong> comme l'<strong>hyperthermie</strong>, l'<strong>hypotension</strong>, les <strong>troubles de la conscience</strong>, l'<strong>incontinence</strong> (par macération) et la <strong>diarrhée</strong>.</li></ul><p>Le piège classique est que l'<strong>âge n'est pas un facteur de risque indépendant</strong> d'escarre ; les personnes âgées sont plus touchées car elles cumulent davantage de comorbidités.</p>"},{"i":"650be4170a7d","n":120,"o":"120-8","u":"Diagnostic positif","t":"Connaître les principaux facteurs de risque d’escarre","q":"Quels sont les facteurs extrinsèques de risque d'escarre ?","a":"<p>Les facteurs extrinsèques de risque d'escarre sont principalement liés à l'appui et comprennent :</p><ul><li>L'<strong>intensité et la durée de la pression</strong> sur les zones d'appui.</li><li>Les <strong>frictions</strong> agressant directement la peau.</li><li>Le <strong>cisaillement</strong>, notamment en position assise ou demi-assise.</li><li>La <strong>macération</strong> due à la sudation ou à l'incontinence.</li><li>Les <strong>éléments traumatisants</strong> en zone d'appui (plis de drap, miettes, contention).</li></ul>"}]};